public class ProjectDataTableModel : ThreadedTableModel<DomainFileInfo, ProjectData> {

	private static bool useNaturalSort = true;

	private ProjectData projectData;
	private volatile int modCount;
	private bool editingOn;

	private bool loadWasCancelled;

	protected ProjectDataTableModel(ServiceProvider serviceProvider) : base("Project Data Table", serviceProvider)
    {
	}

	public static void setUseNaturalSort(bool b) {
		useNaturalSort = b;
	}

	bool loadWasCancelled() {
		return loadWasCancelled;
	}

	/* @Override */
	protected void doLoad(Accumulator<DomainFileInfo> accumulator, TaskMonitor monitor)
    {
		loadWasCancelled = false;
		++modCount;
		if (projectData != null) {
			loadWasCancelled = true;
			DomainFolder rootFolder = projectData.getRootFolder();
			addFiles(accumulator, rootFolder, monitor);
			loadWasCancelled = false;
		}
	}

	private void addFiles(Accumulator<DomainFileInfo> accumulator, DomainFolder folder,
			TaskMonitor monitor)
    {
		DomainFile[] files = folder.getFiles();
		foreach (DomainFile domainFile in files) {
			monitor.checkCancelled();
			accumulator.add(new DomainFileInfo(domainFile, this));
		}
		DomainFolder[] folders = folder.getFolders();
		foreach (DomainFolder domainFolder in folders) {
			monitor.checkCancelled();
			addFiles(accumulator, domainFolder, monitor);
		}
	}

	/* @Override */
	protected TableColumnDescriptor<DomainFileInfo> createTableColumnDescriptor() {
		TableColumnDescriptor<DomainFileInfo> descriptor = new();

		descriptor.addVisibleColumn(new DomainFileTypeColumn());
		descriptor.addVisibleColumn(new DomainFileNameColumn());
		descriptor.addVisibleColumn(new DomainFilePathColumn());
		descriptor.addVisibleColumn(new ModificationDateColumn());

		List<ProjectDataColumn<object>> appSpecificColumns = findAppSpecificColumns();
		foreach (ProjectDataColumn<object> projectDataColumn in appSpecificColumns) {
			if (projectDataColumn.isDefaultColumn()) {
				descriptor.addVisibleColumn(projectDataColumn);
			}
			else {
				descriptor.addHiddenColumn(projectDataColumn);
			}
		}

		return descriptor;
	}

	/* @SuppressWarnings("rawtypes") */
	private List<ProjectDataColumn<object>> findAppSpecificColumns() {
		List<ProjectDataColumn> instances = ClassSearcher.getInstances(typeof(ProjectDataColumn));
		List<ProjectDataColumn<object>> columns = new();

		foreach (ProjectDataColumn projectDataColumn in instances) {
			columns.add(projectDataColumn);
		}
		Collections.sort(columns);
		return columns;
	}

	/* @Override */
	public ProjectData getDataSource() {
		return projectData;
	}

	/* @Override */
	public void refresh() {
		// The modCount allows DomainFileInfo to determine if its cached data is stale relative
		// to this model
		++modCount;
		base.refresh();
	}

	int getModCount() {
		return modCount;
	}

	public void setProjectData(ProjectData projectData) {
		this.projectData = projectData;
		reload();
	}

	/* @Override */
	public bool isCellEditable(int rowIndex, int columnIndex) {
		if (editingOn) {
			DynamicTableColumn<DomainFileInfo,object,object> column = getColumn(columnIndex);
			return column is DomainFileNameColumn;
		}
		return false;
	}

	/* @Override */
	public void setValueAt(object aValue, int rowIndex, int columnIndex) {
		DomainFileInfo info = getRowObject(rowIndex);
		try {
			string newName = aValue.toString();
			DomainFile domainFile = info.getDomainFile();
			if (!domainFile.getName().equals(newName)) {
				domainFile.setName(newName);
			}
		}
		catch (Exception e) when (e is InvalidNameException or DuplicateFileException) {
			Msg.showError(this, null, "Rename Failed", "Invalid name: " + e.getMessage());
		}
		catch (IOException e) {
			Msg.showError(this, null, "Rename Failed",
				"There was a problem renaming the file:\n" + e.getMessage(), e);
		}
	}

	public void setEditing(bool on) {
		editingOn = on;
	}

